import type { ReactNode } from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import { cn } from "../../lib/cn";

/**
 * 单词本的翻页机：左边常驻目录，右边一页一个单词。
 * 翻页是 CSS 3D 合页 —— 右半那张纸绕书脊掀过去，纸背扫过目录并停在上面，
 * 底下就是下一页；往回翻时上一张纸从目录那边摆回来。
 * 翻过去的纸不撤走（`stack`）：一页页盖上去，把目录那一页也盖在下面，
 * 想再看目录得按页内那个「返回目录」——它会把这叠纸摆回右边。
 *
 * 纸背不是白纸：每张纸的背面由调用方用 `backs` 给（这里只管摆位置）。
 * 落定之后左边摊着的那张，永远是「刚翻过去那一页」的纸，背面就照页码取。
 */

const TURN_MS = 620;

interface Turn {
  dir: "fwd" | "bwd";
  from: number;
  to: number;
}

export function WordbookFlip({
  children,
  pages,
  backs,
  index,
  onChange,
  onSwipePast,
  ribbon,
  showNav = true,
  className,
  /** 每 +1 一次：把盖在目录上的纸摆回右边，让人重新看见目录。 */
  contentsSignal = 0,
}: {
  /** 左边的对象：整片左页（目录），由调用方给。 */
  children: ReactNode;
  /** 每页一个单词；页码就是数组下标。 */
  pages: ReactNode[];
  /** 每页那张纸的背面（翻过去以后朝上、摊在左边的那面）。缺了就还是白纸。 */
  backs?: ReactNode[];
  index: number;
  onChange: (index: number) => void;
  /** 在首页继续往回 / 末页继续往前时触发（用来进入复习）。 */
  onSwipePast?: (edge: "start" | "end") => void;
  /** 挂在书口上的那条书签带（跟着当前页走，不跟纸翻）。 */
  ribbon?: ReactNode;
  showNav?: boolean;
  className?: string;
  contentsSignal?: number;
}) {
  const [turn, setTurn] = useState<Turn | null>(null);
  /** 目录上有没有压着翻过去的纸。 */
  const [stack, setStack] = useState(false);
  const [flash, setFlash] = useState(0);
  const timersRef = useRef<number[]>([]);
  const dragRef = useRef<{
    pointerId: number;
    startX: number;
    startY: number;
    lastX?: number;
    lastY?: number;
  } | null>(null);

  const clearTimers = useCallback(() => {
    timersRef.current.forEach((timer) => window.clearTimeout(timer));
    timersRef.current = [];
  }, []);

  useEffect(() => clearTimers, [clearTimers]);

  const reducedMotion = () =>
    typeof window !== "undefined" &&
    window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  /** 落定：往前翻的那张纸留在目录上，往回翻的把纸收走。 */
  const settleTurn = useCallback((next: Turn) => {
    const timer = window.setTimeout(() => {
      timersRef.current = [];
      setTurn(null);
      setStack(next.dir === "fwd");
    }, TURN_MS);
    timersRef.current = [timer];
  }, []);

  const flip = useCallback(
    (dir: "fwd" | "bwd") => {
      if (timersRef.current.length > 0) return;
      const from = index;
      const to = dir === "fwd" ? index + 1 : index - 1;
      if (to < 0 || to >= pages.length) {
        onSwipePast?.(dir === "fwd" ? "end" : "start");
        return;
      }
      if (reducedMotion()) {
        onChange(to);
        setStack(dir === "fwd");
        setFlash((value) => value + 1);
        return;
      }
      const next = { dir, from, to };
      setTurn(next);
      onChange(to);
      settleTurn(next);
    },
    [index, onChange, onSwipePast, pages.length, settleTurn],
  );

  // 页内那个「返回目录」：把压着的那叠纸摆回去，目录重新露出来。
  const uncover = useCallback(() => {
    if (!stack || timersRef.current.length > 0) return;
    if (reducedMotion()) {
      setStack(false);
      return;
    }
    const next: Turn = { dir: "bwd", from: index, to: index };
    setTurn(next);
    settleTurn(next);
  }, [index, settleTurn, stack]);

  const contentsRef = useRef(contentsSignal);
  useEffect(() => {
    if (contentsRef.current === contentsSignal) return;
    contentsRef.current = contentsSignal;
    uncover();
  }, [contentsSignal, uncover]);

  // 从目录直接跳到某一页（隔了好几页）时不做长距离翻飞，轻轻落一页就好。
  const previousIndex = useRef(index);
  useEffect(() => {
    if (previousIndex.current === index) return;
    previousIndex.current = index;
    if (timersRef.current.length === 0) setFlash((value) => value + 1);
  }, [index]);

  // 掀着的那张纸的背面：正面是哪一页，背面就取那一页。往回翻时纸是从左边
  // 摆回来的，它本来就是「上一页」那张（turn.from - 1）——「返回目录」那种
  // 原地摆回（from === to）也归这条。
  const turnBack = turn
    ? (backs?.[turn.dir === "fwd" ? turn.from : turn.from - 1] ?? null)
    : null;

  return (
    <div
      className={cn("wordbook-flip", className)}
      data-turning={turn ? "" : undefined}
      // 挂着书签带的时候，书口那条翻页热区要让出书签占的那一小段，
      // 不然在书签上按下去只会翻书签，翻不了页。
      data-ribbon={ribbon ? "" : undefined}
      onPointerDown={(event) => {
        dragRef.current = {
          pointerId: event.pointerId,
          startX: event.clientX,
          startY: event.clientY,
        };
      }}
      onPointerMove={(event) => {
        const drag = dragRef.current;
        if (!drag || drag.pointerId !== event.pointerId) return;
        // 手势在抬手时才结算：竖着划留给页内滚动，横着划才算翻页。
        drag.lastX = event.clientX;
        drag.lastY = event.clientY;
      }}
      onPointerUp={(event) => {
        const drag = dragRef.current;
        dragRef.current = null;
        if (!drag || drag.pointerId !== event.pointerId) return;
        const dx = (drag.lastX ?? drag.startX) - drag.startX;
        const dy = (drag.lastY ?? drag.startY) - drag.startY;
        if (Math.abs(dx) < 60 || Math.abs(dx) < Math.abs(dy) * 1.4) return;
        flip(dx < 0 ? "fwd" : "bwd");
      }}
      onPointerCancel={() => {
        dragRef.current = null;
      }}
    >
      <div className="wordbook-flip__book">
        {children}
        <article className="wordbook-leaf wordbook-leaf--right">
          <div
            className="wordbook-page-sheet wordbook-page-sheet--entry"
            key={flash}
          >
            {turn?.dir === "bwd" ? pages[turn.from] : pages[index]}
          </div>
        </article>

        {/* 已经翻过去、压在目录上的那些纸：一直摊在那里，朝上的是上一页的背面
            （backs[index - 1]）。回到第一页就没有纸可摊 —— 那时左边本来就该
            露出目录，别拿张纸把它盖住。整片纸背对读屏隐掉：里面写的是上一则的
            摘录，按顺序念一遍只会把正文念串。 */}
        {stack && index > 0 && turn?.dir !== "bwd" ? (
          <div className="wordbook-flip__sheet is-rest" aria-hidden="true">
            <div className="wordbook-flip__face is-back">
              <span className="wordbook-flip__blank" />
              {backs?.[index - 1] ?? null}
            </div>
          </div>
        ) : null}

        {turn ? (
          <div
            className={cn(
              "wordbook-flip__sheet",
              turn.dir === "fwd" ? "is-fwd" : "is-bwd",
            )}
          >
            <div className="wordbook-flip__face">
              <div className="wordbook-page-sheet">
                {turn.dir === "fwd" ? pages[turn.from] : pages[turn.to]}
              </div>
              <span className="wordbook-flip__sheen" aria-hidden="true" />
            </div>
            <div className="wordbook-flip__face is-back" aria-hidden="true">
              <span className="wordbook-flip__blank" />
              {turnBack}
              <span className="wordbook-flip__sheen is-back" />
            </div>
          </div>
        ) : null}

        {turn?.dir === "fwd" ? (
          <span className="wordbook-flip__cast" aria-hidden="true" />
        ) : null}

        <span className="wordbook-spine" aria-hidden="true" />

        {showNav ? (
          <>
            <button
              type="button"
              className="wordbook-flip__edge is-right"
              aria-label="下一页"
              onClick={() => flip("fwd")}
            />

            <div className="wordbook-flip__nav">
              <button
                type="button"
                onClick={() => flip("bwd")}
                aria-label="上一页"
              >
                ‹
              </button>
              <span className="wordbook-flip__count">
                {pages.length === 0 ? 0 : index + 1} / {pages.length}
              </span>
              <button
                type="button"
                onClick={() => flip("fwd")}
                aria-label="下一页"
              >
                ›
              </button>
            </div>
          </>
        ) : null}
      </div>
      {ribbon}
    </div>
  );
}
